import{_ as s,a0 as r,w as a,s as d,ao as p,I as l,x as e,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"RHCSA 系列（一）: 回顧基礎命令及系統文檔 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（一）: 回顧基礎命令及系統文檔 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（一）: 回顧基礎命令及系統文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（一）: 回顧基礎命令及系統文檔 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 01--Reviewing Essential Commands and System Documentation","title":"RHCSA 系列（一）: 回顧基礎命令及系統文檔","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 01--Reviewing Essential Commands and System Documentation.md","filePath":"[post].md"}'),m={name:"RHCSA Series/RHCSA Series--Part 01--Reviewing Essential Commands and System Documentation.md"};function u(c,t,w,f,g,x){const n=r("Link");return a(),d("div",null,[t[34]||(t[34]=p('<h1 id="rhcsa-系列-一-回顧基礎命令及系統文檔" tabindex="-1">RHCSA 系列（一）: 回顧基礎命令及系統文檔 <a class="header-anchor" href="#rhcsa-系列-一-回顧基礎命令及系統文檔" aria-label="Permalink to “RHCSA 系列（一）: 回顧基礎命令及系統文檔”">​</a></h1><p>RHCSA (紅帽認證系統工程師) 是由 RedHat 公司舉行的認證考試，這家公司給商業公司提供開源操作系統和軟件，除此之外，還為這些企業和機構提供支持、訓練以及諮詢服務等。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/RHCSA-Series-by-Tecmint.png" alt="RHCSA Exam Guide"></p><p><em>RHCSA 考試準備指南</em></p><p>RHCSA 考試(考試編號 EX200)通過後可以獲取由 RedHat 公司頒發的證書. RHCSA 考試是 RHCT(紅帽認證技師)的升級版，而且 RHCSA 必須在新的 Red Hat Enterprise Linux(紅帽企業版)下完成。RHCT 和 RHCSA 的主要變化就是 RHCT 基於 RHEL5，而 RHCSA 基於 RHEL6 或者7，這兩個認證的等級也有所不同。</p><p>紅帽認證管理員最起碼可以在紅帽企業版的環境下執行如下系統管理任務：</p><ul><li>理解並會使用命令管理文件、目錄、命令列以及系統/軟件包的文檔</li><li>在不同的啓動等級操作運行中的系統，識別和控制進程，啓動或停止虛擬機</li><li>使用分區和邏輯卷管理本地存儲</li><li>創建並且配置本地文件系統和網絡文件系統，設置他們的屬性(權限、加密、訪問控制表)</li><li>部署、配置、並且控制系統，包括安裝、升級和卸載軟件</li><li>管理系統用户和組，以及使用集中制的 LDAP 目錄進行用户驗證</li><li>確保系統安全，包括基礎的防火牆規則和 SELinux 配置</li></ul>',7)),l("p",null,[t[1]||(t[1]=e("關於你所在國家的考試註冊和費用請參考 ",-1)),i(n,{href:"https://www.redhat.com/en/services/certification/rhcsa"},{default:o(()=>[...t[0]||(t[0]=[e("RHCSA 認證頁面",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[35]||(t[35]=p('<p>在這個有15章的 RHCSA(紅帽認證管理員)備考系列中，我們將覆蓋以下的關於紅帽企業 Linux 第七版的最新的信息：</p><ul><li>Part 1: 回顧基礎命令及系統文檔</li><li>Part 2: 在 RHEL7 中如何進行文件和目錄管理</li><li>Part 3: 在 RHEL7 中如何管理用户和組</li><li>Part 4: 使用 nano 和 vim 管理命令，使用 grep 和正則表達式分析文本</li><li>Part 5: RHEL7 的進程管理：啓動，關機，以及這之間的各種事情</li><li>Part 6: 使用 &#39;Parted&#39; 和 &#39;SSM&#39; 來管理和加密系統存儲</li><li>Part 7: 使用 ACL(訪問控制表)並掛載 Samba/NFS 文件分享</li><li>Part 8: 加固 SSH，設置主機名並開啓網絡服務</li><li>Part 9: 安裝、配置和加固一個 Web 和 FTP 服務器</li><li>Part 10: Yum 包管理方式，使用 Cron 進行自動任務管理以及監控系統日誌</li><li>Part 11: 使用 FirewallD 和 Iptables 設置防火牆，控制網絡流量</li><li>Part 12: 使用 Kickstart 自動安裝 RHEL 7</li><li>Part 13: RHEL7：什麼是 SeLinux？他的原理是什麼？</li><li>Part 14: 在 RHEL7 中使用基於 LDAP 的權限控制</li><li>Part 15: 虛擬化基礎和用KVM管理虛擬機</li></ul><p>在第一章，我們講解如何在終端或者 Shell 窗口輸入和運行正確的命令，並且講解如何找到、查閲，以及使用系統文檔。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Reviewing-Essential-Linux-Commands.png" alt="RHCSA: Reviewing Essential Linux Commands – Part 1"></p><p><em>RHCSA：回顧必會的 Linux 命令 - 第一部分</em></p><h4 id="前提" tabindex="-1">前提: <a class="header-anchor" href="#前提" aria-label="Permalink to “前提:”">​</a></h4><p>至少你要熟悉如下命令</p>',7)),l("ul",null,[l("li",null,[i(n,{href:"http://linux.cn/article-2479-1.html"},{default:o(()=>[...t[3]||(t[3]=[e("cd 命令",-1)])]),_:1}),t[4]||(t[4]=e(" (改變目錄)",-1))]),l("li",null,[i(n,{href:"https://linux.cn/article-5109-1.html"},{default:o(()=>[...t[5]||(t[5]=[e("ls 命令",-1)])]),_:1}),t[6]||(t[6]=e(" (列舉文件)",-1))]),l("li",null,[i(n,{href:"http://linux.cn/article-2687-1.html"},{default:o(()=>[...t[7]||(t[7]=[e("cp 命令",-1)])]),_:1}),t[8]||(t[8]=e(" (複製文件)",-1))]),l("li",null,[i(n,{href:"http://www.tecmint.com/rename-multiple-files-in-linux/"},{default:o(()=>[...t[9]||(t[9]=[e("mv 命令",-1)])]),_:1}),t[10]||(t[10]=e(" (移動或重命名文件)",-1))]),l("li",null,[i(n,{href:"http://linux.cn/article-2740-1.html"},{default:o(()=>[...t[11]||(t[11]=[e("touch 命令",-1)])]),_:1}),t[12]||(t[12]=e(" (創建一個新的文件或更新已存在文件的時間表)",-1))]),t[13]||(t[13]=l("li",null,"rm 命令 (刪除文件)",-1)),t[14]||(t[14]=l("li",null,"mkdir 命令 (創建目錄)",-1))]),t[36]||(t[36]=l("p",null,"在這篇文章中你將會找到更多的關於如何更好的使用他們的正確用法和特殊用法.",-1)),t[37]||(t[37]=l("p",null,"雖然沒有嚴格的要求，但是作為討論常用的 Linux 命令和在 Linux 中搜索信息方法，你應該安裝 RHEL7 來嘗試使用文章中提到的命令。這將會使你學習起來更省力。",-1)),l("ul",null,[l("li",null,[i(n,{href:"http://www.tecmint.com/redhat-enterprise-linux-7-installation/"},{default:o(()=>[...t[15]||(t[15]=[e("紅帽企業版 Linux(RHEL)7 安裝指南",-1)])]),_:1})])]),t[38]||(t[38]=p('<h3 id="使用-shell-進行交互" tabindex="-1">使用 Shell 進行交互 <a class="header-anchor" href="#使用-shell-進行交互" aria-label="Permalink to “使用 Shell 進行交互”">​</a></h3><p>如果我們使用文本模式登錄 Linux，我們就會直接進入到我們的默認 shell 中。另一方面，如果我們使用圖形化界面登錄，我們必須通過啓動一個終端來開啓 shell。無論那種方式，我們都會看到用户提示符，並且我們可以在這裏輸入並且執行命令(當按下回車時，命令就會被執行)。</p><p>命令是由兩個部分組成的：</p><ul><li>命令本身</li><li>參數</li></ul><p>某些參數，稱為選項（通常使用一個連字符開頭），會改變命令的行為方式，而另外一些則指定了命令所操作的對象。</p><p>type 命令可以幫助我們識別某一個特定的命令是由 shell 內置的還是由一個單獨的包提供的。這樣的區別在於我們能夠在哪裏找到更多關於該命令的更多信息。對 shell 內置的命令，我們需要看 shell 的手冊頁；如果是其他的，我們需要看軟件包自己的手冊頁。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-shell-built-in-Commands.png" alt="Check Shell built in Commands"></p><p><em>檢查Shell的內置命令</em></p><p>在上面的例子中， <code>cd</code> 和 <code>type</code> 是 shell 內置的命令，<code>top</code> 和 <code>less</code> 是由 shell 之外的其他的二進制文件提供的(在這種情況下，type將返回命令的位置)。</p><p>其他的內置命令：</p>',10)),l("ul",null,[l("li",null,[i(n,{href:"https://linux.cn/article-3948-1.html"},{default:o(()=>[...t[16]||(t[16]=[e("echo 命令",-1)])]),_:1}),t[17]||(t[17]=e(": 展示字符串",-1))]),l("li",null,[i(n,{href:"https://linux.cn/article-3422-1.html"},{default:o(()=>[...t[18]||(t[18]=[e("pwd 命令",-1)])]),_:1}),t[19]||(t[19]=e(": 輸出當前的工作目錄",-1))])]),t[39]||(t[39]=p(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/More-Built-in-Shell-Commands.png" alt="More Built in Shell Commands"></p><p><em>其它內置命令</em></p><p><strong>exec 命令</strong></p><p>它用來運行我們指定的外部程序。請注意在多數情況下，只需要輸入我們想要運行的程序的名字就行，不過<code> exec</code> 命令有一個特殊的特性：不是在 shell 之外創建新的進程運行，而是這個新的進程會替代原來的 shell，可以通過下列命令來驗證。</p><pre><code># ps -ef | grep [shell 進程的PID]
</code></pre><p>當新的進程終止時，Shell 也隨之終止。運行 <code>exec top</code> ，然後按下 <code>q</code> 鍵來退出 top，你會注意到 shell 會話也同時終止，如下面的屏幕錄像展示的那樣:</p>`,6)),t[40]||(t[40]=l("iframe",{width:"640",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"https://dn-linuxcn.qbox.me/static/video/Linux%20exec%20Command%20Demonstration.mp4"},null,-1)),t[41]||(t[41]=l("p",null,[l("strong",null,"export 命令")],-1)),t[42]||(t[42]=l("p",null,"給之後執行的命令的輸出環境變量。",-1)),t[43]||(t[43]=l("p",null,[l("strong",null,"history 命令")],-1)),t[44]||(t[44]=l("p",null,[e("展示數行之前的歷史命令。命令編號前面前綴上感嘆號可以再次執行這個命令。如果我們需要編輯歷史列表中的命令，我們可以按下 "),l("code",null,"Ctrl + r"),e(" 並輸入與命令相關的第一個字符。我們可以看到的命令會自動補全，可以根據我們目前的需要來編輯它：")],-1)),t[45]||(t[45]=l("iframe",{width:"640",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"https://dn-linuxcn.qbox.me/static/video/Linux%20history%20Command%20Demonstration.mp4"},null,-1)),t[46]||(t[46]=p(`<p>命令列表會保存在一個叫 <code>.bash_history</code> 的文件裏。<code>history</code> 命令是一個非常有用的用於減少輸入次數的工具，特別是進行命令列編輯的時候。默認情況下，bash 保留最後輸入的500個命令，不過可以通過修改 HISTSIZE 環境變量來增加:</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Linux-history-Command.png" alt="Linux history Command"></p><p><em>Linux history 命令</em></p><p>但上述變化，在我們的下一次啓動不會保留。為了保持 HISTSIZE 變量的變化，我們需要通過手工修改文件編輯：</p><pre><code># 要設置 history 長度，請看 bash(1)文檔中的 HISTSIZE 和 HISTFILESIZE
HISTSIZE=1000
</code></pre><p><strong>重要</strong>： 我們的更改不會立刻生效，除非我們重啓了 shell 。</p><p><strong>alias 命令</strong></p><p>沒有參數或使用 <code>-p</code> 選項時將會以“名稱=值”的標準形式輸出別名列表。當提供了參數時，就會按照給定的名字和值定義一個別名。</p><p>使用 <code>alias</code> ，我們可以創建我們自己的命令，或使用所需的參數修改現有的命令。舉個例子，假設我們將 <code>ls</code> 定義別名為 <code>ls –color=auto</code> ，這樣就可以使用不同顏色輸出文件、目錄、鏈接等等。</p><pre><code># alias ls=&#39;ls --color=auto&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Linux-alias-Command.png" alt="Linux alias Command"></p><p><em>Linux 別名命令</em></p><p><strong>注意</strong>： 你可以給你的“新命令”起任何的名字，並且使用單引號包括很多命令，但是你要用分號區分開它們。如下：</p><pre><code># alias myNewCommand=&#39;cd /usr/bin; ls; cd; clear&#39;
</code></pre><p><strong>exit 命令</strong></p><p><code>exit</code> 和 <code>logout</code> 命令都可以退出 shell 。<code>exit</code> 命令可以退出所有的 shell，<code>logout</code> 命令只註銷登錄的 shell（即你用文本模式登錄時自動啓動的那個）。</p><p><strong>man 和 info 命令</strong> 如果你對某個程序有疑問，可以參考它的手冊頁，可以使用 <code>man</code> 命令調出它。此外，還有一些關於重要文件(inittab、fstab、hosts 等等)、庫函數、shell、設備及其他功能的手冊頁。</p><p>舉例:</p><ul><li>man uname (輸出系統信息，如內核名稱、處理器、操作系統類型、架構等)</li><li>man inittab (初始化守護進程的設置)</li></ul><p>另外一個重要的信息的來源是由 <code>info</code> 命令提供的，<code>info</code> 命令常常被用來讀取 info 文件。這些文件往往比手冊頁 提供了更多信息。可以通過 <code>info keyword</code> 調用某個命令的信息：</p><pre><code># info ls
# info cut
</code></pre><p>另外，在 <code>/usr/share/doc</code> 文件夾包含了大量的子目錄，裏面可以找到大量的文檔。它們是文本文件或其他可讀格式。</p><p>你要習慣於使用這三種方法去查找命令的信息。重點關注每個命令文檔中介紹的詳細的語法。</p><p><strong>使用 expand 命令把製表符轉換為空格</strong></p><p>有時候文本文檔包含了製表符，但是程序無法很好的處理。或者我們只是簡單的希望將製表符轉換成空格。這就是用到 <code>expand</code> 地方(由GNU核心組件包提供) 。</p><p>舉個例子，我們有個文件 NumberList.txt，讓我們使用 <code>expand</code> 處理它，將製表符轉換為一個空格，並且顯示在標準輸出上。</p><pre><code># expand --tabs=1 NumbersList.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Linux-expand-Command.png" alt="Linux expand Command"></p><p><em>Linux expand 命令</em></p><p>unexpand命令可以實現相反的功能(將空格轉為製表符)</p><p><strong>使用 head 輸出文件首行及使用 tail 輸出文件尾行</strong></p><p>通常情況下，<code>head</code> 命令後跟着文件名時，將會輸出該文件的前十行，我們可以通過 <code>-n</code> 參數來自定義具體的行數。</p><pre><code># head -n3 /etc/passwd
# tail -n3 /etc/passwd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Linux-head-and-tail-Command.png" alt="Linux head and tail Command"></p><p><em>Linux 的 head 和 tail 命令</em></p><p><code>tail</code> 最有意思的一個特性就是能夠顯示增長的輸入文件(<code>tail -f my.log</code>，my.log 是我們需要監視的文件。)這在我們監控一個持續增加的日誌文件時非常有用。</p>`,36)),l("ul",null,[l("li",null,[i(n,{href:"http://www.tecmint.com/view-contents-of-file-in-linux/"},{default:o(()=>[...t[20]||(t[20]=[e("使用 head 和 tail 命令有效地管理文件",-1)])]),_:1})])]),t[47]||(t[47]=p(`<p><strong>使用 paste 按行合併文本文件</strong></p><p><code>paste</code> 命令一行一行的合併文件，默認會以製表符來區分每個文件的行，或者你可以自定義的其它分隔符。(下面的例子就是輸出中的字段使用等號分隔)。</p><pre><code># paste -d= file1 file2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Merge-Files-in-Linux-with-paste-command.png" alt="Merge Files in Linux"></p><p><em>Linux 中的 merge 命令</em></p><p><strong>使用 split 命令將文件分塊</strong></p><p><code>split</code> 命令常常用於把一個文件切割成兩個或多個由我們自定義的前綴命名的文件。可以根據大小、區塊、行數等進行切割，生成的文件會有一個數字或字母的後綴。在下面的例子中，我們將切割 bash.pdf ，每個文件 50KB (-b 50KB)，使用數字後綴 (-d)：</p><pre><code># split -b 50KB -d bash.pdf bash_
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Split-Files-in-Linux-with-split-command.png" alt="Split Files in Linux"></p><p><em>在 Linux 下切割文件</em></p><p>你可以使用如下命令來合併這些文件，生成原來的文件:</p><pre><code># cat bash_00 bash_01 bash_02 bash_03 bash_04 bash_05 &gt; bash.pdf
</code></pre><p><strong>使用 tr 命令替換字符</strong></p><p><code>tr</code> 命令多用於一對一的替換（改變）字符，或者使用字符範圍。和之前一樣，下面的實例我們將使用之前的同樣文件file2，我們將做：</p><ul><li><p>小寫字母 o 變成大寫</p></li><li><p>所有的小寫字母都變成大寫字母</p></li><li><h1 id="cat-file2-tr-o-o" tabindex="-1">cat file2 | tr o O <a class="header-anchor" href="#cat-file2-tr-o-o" aria-label="Permalink to “cat file2 | tr o O”">​</a></h1><h1 id="cat-file2-tr-a-z-a-z" tabindex="-1">cat file2 | tr [a-z] [A-Z] <a class="header-anchor" href="#cat-file2-tr-a-z-a-z" aria-label="Permalink to “cat file2 | tr [a-z] [A-Z]”">​</a></h1></li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Translate-characters-in-Linux-with-tr-command.png" alt="Translate Characters in Linux"></p><p><em>在 Linux 中替換字符</em></p><p><strong>使用 uniq 和 sort 檢查或刪除重複的文字</strong></p><p><code>uniq</code> 命令可以幫我們查出或刪除文件中的重複的行，默認會輸出到標準輸出，我們應當注意，<code>uniq</code>只能查出相鄰的相同行，所以，<code>uniq</code> 往往和 <code>sort</code> 一起使用(<code>sort</code> 一般用於對文本文件的內容進行排序)</p><p>默認情況下，<code>sort</code> 以第一個字段(使用空格分隔)為關鍵字段。想要指定不同關鍵字段，我們需要使用 -k 參數，請注意如何使用 <code>sort</code> 和 <code>uniq</code> 輸出我們想要的字段，具體可以看下面的例子：</p><pre><code># cat file3
# sort file3 | uniq
# sort -k2 file3 | uniq
# sort -k3 file3 | uniq
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Remove-Duplicate-Lines-in-file.png" alt="刪除文件中重複的行"></p><p><em>刪除文件中重複的行</em></p><p><strong>從文件中提取文本的命令</strong></p><p><code>cut</code> 命令基於字節(-b)、字符(-c)、或者字段(-f)的數量，從輸入文件（標準輸入或文件）中提取到的部分將會以標準輸出上。</p><p>當我們使用字段 <code>cut</code> 時，默認的分隔符是一個製表符，不過你可以通過 -d 參數來自定義分隔符。</p><pre><code># cut -d: -f1,3 /etc/passwd # 這個例子提取了第一和第三字段的文本
# cut -d: -f2-4 /etc/passwd # 這個例子提取了第二到第四字段的文本
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Extract-Text-from-a-file.png" alt="從文件中提取文本"></p><p><em>從文件中提取文本</em></p><p>注意，簡潔起見，上方的兩個輸出的結果是截斷的。</p><p><strong>使用 fmt 命令重新格式化文件</strong></p><p><code>fmt</code> 被用於去“清理”有大量內容或行的文件，或者有多級縮進的文件。新的段落格式每行不會超過75個字符寬，你能通過 -w (width 寬度)參數改變這個設定，它可以設置行寬為一個特定的數值。</p><p>舉個例子，讓我們看看當我們用 <code>fmt</code> 顯示定寬為100個字符的時候的文件 /etc/passwd 時會發生什麼。再次，輸出截斷了。</p><pre><code># fmt -w100 /etc/passwd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/File-Reformatting-in-Linux-with-fmt-command.png" alt="File Reformatting in Linux"></p><p><em>Linux 文件重新格式化</em></p><p><strong>使用 pr 命令格式化打印內容</strong></p><p><code>pr</code> 分頁並且在按列或多列的方式顯示一個或多個文件。 換句話説，使用 <code>pr</code> 格式化一個文件使它打印出來時看起來更好。舉個例子，下面這個命令：</p><pre><code># ls -a /etc | pr -n --columns=3 -h &quot;Files in /etc&quot;
</code></pre><p>以一個友好的排版方式(3列)輸出/etc下的文件，自定義了頁眉(通過 -h 選項實現)、行號(-n)。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/File-Formatting-in-Linux-with-pr-command.png" alt="File Formatting in Linux"></p><p><em>Linux的文件格式化</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇文章中，我們已經討論瞭如何在 Shell 或終端以正確的語法輸入和執行命令，並解釋如何找到，查閲和使用系統文檔。正如你看到的一樣簡單，這就是你成為 RHCSA 的第一大步。</p><p>如果你希望添加一些其他的你經常使用的能夠有效幫你完成你的日常工作的基礎命令，並願意分享它們，請在下方留言。也歡迎提出問題。我們期待您的回覆。</p><hr>`,46)),l("p",null,[t[22]||(t[22]=e("via: ",-1)),i(n,{href:"http://www.tecmint.com/rhcsa-exam-reviewing-essential-commands-system-documentation/"},{default:o(()=>[...t[21]||(t[21]=[e("http://www.tecmint.com/rhcsa-exam-reviewing-essential-commands-system-documentation/",-1)])]),_:1})]),l("p",null,[t[26]||(t[26]=e("作者：",-1)),i(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:o(()=>[...t[23]||(t[23]=[e("Gabriel Cánepa",-1)])]),_:1}),t[27]||(t[27]=e(" 譯者：",-1)),i(n,{href:"https://github.com/xiqingongzi"},{default:o(()=>[...t[24]||(t[24]=[e("xiqingongzi",-1)])]),_:1}),t[28]||(t[28]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[25]||(t[25]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[31]||(t[31]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[29]||(t[29]=[e("LCTT",-1)])]),_:1}),t[32]||(t[32]=e(" 原創翻譯，",-1)),i(n,{href:"https://linux.cn/"},{default:o(()=>[...t[30]||(t[30]=[e("Linux中國",-1)])]),_:1}),t[33]||(t[33]=e(" 榮譽推出",-1))])])}const L=s(m,[["render",u]]);export{h as __pageData,L as default};
